import './neon-loading-indicator.scss';
import { NeonWidget } from '../shared/neon-widget';
import { createElement, dynamicText, updateDynamicText, } from '../shared/dom-manipulation';
import { translate, addTranslationListener } from '@ps-refarch-ux/mfe-utils';
export class NeonLoadingIndicator extends NeonWidget {
    constructor() {
        super(...arguments);
        this.widgetTag = 'neon-loading-indicator';
        this.isLoading = true;
    }
    render() {
        return createElement('div', {
            attrs: {
                class: 'neon-loading-indicator',
                role: 'alert',
                'aria-live': 'assertive'
            }
        }, createElement('p', {
            text: dynamicText(() => { return this.isLoading ? translate('neon|loading indicator|content is loading') : translate('neon|loading indicator|content has loaded'); }),
            attrs: {
                class: 'neon-sr-only',
            }
        }));
    }
    connectedCallback() {
        super.connectedCallback();
        this.i18nUnsubscribe = addTranslationListener(() => {
            updateDynamicText(this);
        });
    }
    disconnectedCallback() {
        this.isLoading = false;
        updateDynamicText(this);
        if (this.i18nUnsubscribe != null) {
            this.i18nUnsubscribe();
            this.i18nUnsubscribe = undefined;
        }
    }
}
